import collections

def transform(grid):
    g = np.array(grid)
    bg = background(g)

    # Frame: bounding box of the four colour-4 corner markers.
    ys, xs = np.where(g == 4)
    y0, x0, y1, x1 = ys.min(), xs.min(), ys.max(), xs.max()
    out = g[y0:y1 + 1, x0:x1 + 1].copy()
    emit(out, "Crop the region framed by the four colour-4 corner markers.")

    # Template: the non-background cells outside the frame, at scale 1.
    tmpl = {}
    for y in range(g.shape[0]):
        for x in range(g.shape[1]):
            if g[y, x] != bg and not (y0 <= y <= y1 and x0 <= x <= x1):
                tmpl[(y, x)] = int(g[y, x])
    ty0 = min(p[0] for p in tmpl)
    tx0 = min(p[1] for p in tmpl)
    rel = {(y - ty0, x - tx0): c for (y, x), c in tmpl.items()}
    counts = collections.Counter(rel.values())

    # Anchor: a big block inside the frame whose colour occurs once in the template.
    inside = [o for o in objects(out, bg=bg) if o["colour"] != 4]
    anchor = None
    for o in inside:
        if counts.get(o["colour"], 0) == 1:
            anchor = o
            break
    if anchor is None:
        anchor = max(inside, key=lambda o: o["size"])
    k = anchor["box"][2] - anchor["box"][0] + 1
    cell = [p for p, c in rel.items() if c == anchor["colour"]][0]
    oy = anchor["box"][0] - k * cell[0]
    ox = anchor["box"][1] - k * cell[1]

    # Stamp every template cell as a k x k block, in reading order.
    H, W = out.shape
    for (ry, rx), c in sorted(rel.items()):
        by, bx = oy + k * ry, ox + k * rx
        for yy in range(by, by + k):
            for xx in range(bx, bx + k):
                if 0 <= yy < H and 0 <= xx < W:
                    out[yy, xx] = c
        emit(out, f"Stamp template cell ({ry},{rx}) colour {c} as a {k}x{k} block at ({by},{bx}).")

    emit(out, "Final: the template drawn at block scale, aligned with the existing blocks.")
    return out
